import java.util.*;

class Solution {
  private static final int LIMIT = 1_000_000;
  private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

  public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
    Set<Long> blockedSet = new HashSet<>();
    for (int[] cell : blocked) blockedSet.add(key(cell[0], cell[1]));
    int boundary = blocked.length * (blocked.length - 1) / 2;
    return canReach(source, target, blockedSet, boundary)
        && canReach(target, source, blockedSet, boundary);
  }

  private boolean canReach(int[] start, int[] goal, Set<Long> blocked, int boundary) {
    Set<Long> visited = new HashSet<>();
    ArrayDeque<int[]> queue = new ArrayDeque<>();
    queue.offer(start);
    visited.add(key(start[0], start[1]));
    while (!queue.isEmpty() && visited.size() <= boundary) {
      int[] cell = queue.poll();
      if (cell[0] == goal[0] && cell[1] == goal[1]) return true;
      for (int[] direction : DIRECTIONS) {
        int row = cell[0] + direction[0], column = cell[1] + direction[1];
        if (row < 0 || row >= LIMIT || column < 0 || column >= LIMIT) continue;
        long next = key(row, column);
        if (!blocked.contains(next) && visited.add(next)) queue.offer(new int[] {row, column});
      }
    }
    return visited.size() > boundary;
  }

  private long key(int row, int column) {
    return ((long) row << 20) | column;
  }
}
